import type { PokedexSnapshot } from '../bus/snapshots.js';

function cardsSig(cards: PokedexSnapshot['cards']): string {
  return cards.map((c) =>
    `${c.cardKey}|${c.displayName}|${c.count}|${c.shinyCount}|${c.shadowCount}|${c.hasShiny ? 1 : 0}|${c.hasShadow ? 1 : 0}|${c.isDiscovered ? 1 : 0}`,
  ).join(';');
}

function uiSig(ui: PokedexSnapshot['ui']): string {
  return JSON.stringify(ui);
}

export function pokedexSnapshotWouldChange(prev: PokedexSnapshot, next: PokedexSnapshot): boolean {
  return (
    prev.languageTag !== next.languageTag ||
    uiSig(prev.ui) !== uiSig(next.ui) ||
    prev.pokedexCount !== next.pokedexCount ||
    prev.pokedexTotal !== next.pokedexTotal ||
    prev.pokedexPercent !== next.pokedexPercent ||
    prev.pokedexMissingCount !== next.pokedexMissingCount ||
    prev.selectedGen !== next.selectedGen ||
    prev.filterMissingActive !== next.filterMissingActive ||
    prev.filterShinyActive !== next.filterShinyActive ||
    prev.collectionOwnershipFilter !== next.collectionOwnershipFilter ||
    prev.collectionGlobalSummaryHtml !== next.collectionGlobalSummaryHtml ||
    JSON.stringify(prev.genChips) !== JSON.stringify(next.genChips) ||
    prev.activeSubTab !== next.activeSubTab ||
    JSON.stringify(prev.sortButtons) !== JSON.stringify(next.sortButtons) ||
    prev.collectionToolbarHtml !== next.collectionToolbarHtml ||
    prev.collectionTabsHtml !== next.collectionTabsHtml ||
    prev.collectionTabsClass !== next.collectionTabsClass ||
    prev.collectionBonusesHtml !== next.collectionBonusesHtml ||
    prev.cardsEmptyMessage !== next.cardsEmptyMessage ||
    cardsSig(prev.cards) !== cardsSig(next.cards)
  );
}
